const durations=[14,16,20,18,20,18,18,16,10];
const total=durations.reduce((a,b)=>a+b,0)*30;
const ease=(f:number,start=0,end=30)=>interpolate(f,[start,end],[0,1],{extrapolateLeft:'clamp',extrapolateRight:'clamp'});

const Reveal:React.FC<{children:React.ReactNode,delay?:number}>=({children,delay=0})=>{const f=useCurrentFrame();const p=ease(f,delay,delay+24);return <div style={{opacity:p,transform:`translateY(${(1-p)*22}px)`}}>{children}</div>};
const Title:React.FC<{kicker:string,title:string}>=({kicker,title})=><><div style={{fontSize:22,color:T.accent,letterSpacing:3,textTransform:'uppercase',marginBottom:24}}>{kicker}</div><h1 style={{fontSize:76,letterSpacing:-3,lineHeight:1.08,fontWeight:600,margin:'0 0 48px',maxWidth:1650}}>{title}</h1></>;
const Source:React.FC<{children:React.ReactNode}>=({children})=><div style={{position:'absolute',bottom:52,left:104,fontSize:19,color:T.muted,maxWidth:1610,lineHeight:1.4}}>{children}</div>;
const Big:React.FC<{value:string,label:string,note?:string}>=({value,label,note})=><div><div style={{fontSize:110,letterSpacing:-5,color:T.accent,lineHeight:1.1}}>{value}</div><div style={{fontSize:30,marginTop:20}}>{label}</div>{note&&<div style={{fontSize:22,color:T.muted,marginTop:12}}>{note}</div>}</div>;
const Bar:React.FC<{label:string,value:number,delay?:number,color?:string}>=({label,value,delay=0,color=T.accent})=>{const f=useCurrentFrame();return <div style={{display:'flex',alignItems:'center',gap:24,marginBottom:0}}><div style={{width:100,fontSize:27,color:T.muted}}>{label}</div><div style={{height:34,background:T.line,width:1080}}><div style={{height:34,width:`${value*ease(f,delay,delay+42)}%`,background:color}}/></div><div style={{fontSize:30,minWidth:100}}>{value.toFixed(1)}%</div></div>};

const Scene:React.FC<{i:number}>=({i})=>{const f=useCurrentFrame();return <AbsoluteFill style={{background:T.bg,color:T.ink,fontFamily:T.font,padding:'80px 104px',opacity:Math.min(ease(f,0,16),1-ease(f,durations[i]*30-16,durations[i]*30))}}>
<div style={{position:'absolute',right:100,top:80,color:T.muted,fontSize:21}}>HAGGLE / EHL FINALS</div>
{i===0&&<><Reveal><div style={{fontSize:26,color:T.accent,letterSpacing:4,marginTop:50}}>THE BUILD · THE EVIDENCE · THE LESSONS</div><h1 style={{fontSize:142,fontWeight:600,letterSpacing:-8,lineHeight:1.02,margin:'55px 0 35px'}}>Better deals.<br/>Every move explained.</h1><div style={{fontSize:35,color:T.muted,lineHeight:1.5,maxWidth:1200}}>An autonomous procurement negotiator built and tested through one hackathon night.</div></Reveal><Reveal delay={45}><div style={{marginTop:55,display:'flex',gap:100}}><Big value="77.2%" label="latest complete practice suite"/><Big value="€1.17m" label="modeled cost reduction" note="10 simulated cases · not realized savings"/></div></Reveal><Source>Repository snapshot: 11 Oct 2026, 09:08 CEST · hosted practice results, not Live Final results.</Source></>}
{i===1&&<><Title kicker="01 / THE SPRINT" title="From inspection to autonomous negotiation."/><div style={{display:'flex',gap:100,marginBottom:65}}><Big value={String(evidence.commitCount)} label="commits in the review window"/><Big value="312" label="archived run records" note="310 online · 2 offline · mixed models and probes"/></div><svg width="1680" height="250" viewBox="0 0 1680 250"><line x1="40" y1="50" x2="1600" y2="50" stroke={T.line} strokeWidth="4"/>{[['13:33','Import + starting point'],['17:20','Inspectable workbench'],['19:07','Code owns the prices'],['23:53','Crash recovery'],['08:48','Slow-supplier protection']].map(([time,label],j)=><g key={time} opacity={ease(f,j*15+15,j*15+40)}><circle cx={40+j*390} cy="50" r="9" fill={T.accent}/><text x={Math.min(40+j*390,1370)} y="109" fill={T.accent} fontSize="30">{time}</text><text x={Math.min(40+j*390,1370)} y="154" fill={T.ink} fontSize="23">{label}</text></g>)}</svg><Source>CEST; 10–11 Oct. Initial import included; inherited template history excluded. Run records are not independent experiments.</Source></>}
{i===2&&<><Title kicker="02 / THE CORE IDEA" title="The model writes. Code does the math."/><div style={{display:'flex',alignItems:'stretch',gap:42,marginTop:80}}>{[['01','Verified facts','Prices, forecasts, indices, quality and rival offers.'],['02','Cost engine','Compare payment, risk, clauses and coverage in total cost C.'],['03','Equal-cost menu','Offer several structures with the same cost to the buyer.'],['04','Language model','Read supplier priorities and choose a persuasive package.']].map(([n,title,body],j)=><React.Fragment key={n}><div style={{flex:1,borderTop:`3px solid ${T.accent}`,paddingTop:30,opacity:ease(f,j*20,j*20+30)}}><div style={{fontSize:26,color:T.accent}}>{n}</div><h2 style={{fontSize:36,fontWeight:500,marginTop:35}}>{title}</h2><div style={{fontSize:29,lineHeight:1.5,color:T.muted}}>{body}</div></div></React.Fragment>)}</div><Reveal delay={100}><div style={{marginTop:90,fontSize:36}}>Every number and claim has an inspectable source.</div></Reveal><Source>Source: docs/design.md; haggle/economics.py, strategy.py, context.py and agent.py. One general playbook for unseen cases.</Source></>}
{i===3&&<><Title kicker="03 / MEASURED IMPACT" title="€1.17m lower modeled total cost."/><div style={{display:'flex',gap:100,alignItems:'center'}}><div style={{width:1050}}>{[['Opening offers',12.75951063,T.muted],['Negotiated deals',11.59134912,T.accent]].map(([label,n,color],j)=><div key={String(label)} style={{margin:'55px 0'}}><div style={{fontSize:32,marginBottom:18}}>{label}</div><div style={{height:82,width:1000,background:T.line}}><div style={{height:82,width:1000*(Number(n)/13)*ease(f,20+j*20,80+j*20),background:String(color)}}/></div><div style={{fontSize:38,marginTop:15}}>€{Number(n).toFixed(2)}m</div></div>)}</div><div><Big value="−9.2%" label="across the same ten cases"/><div style={{fontSize:30,lineHeight:1.5,color:T.muted,maxWidth:430,marginTop:38}}>Payment, index risk and supply terms count alongside unit price.</div></div></div><Source>Latest complete ten-case suite: 20261011-014457. Sum of logged C_open and C_deal; simulated cost, not realized savings.</Source></>}
