{i===5&&<><Title kicker="05 / THE SCORECARD" title="Ten cases. Ten deals. 77.2% mean score."/><div style={{display:'flex',gap:100}}><div style={{width:1390}}>{evidence.latestSuite.map((c,j)=><div key={j} style={{marginBottom:20}}><Bar label={c.case} value={c.score} delay={j*4}/></div>)}</div><div style={{width:240,paddingTop:80,fontSize:29,lineHeight:1.5,color:T.muted}}><div style={{fontSize:62,color:T.accent}}>+12.0</div><div style={{fontSize:23}}>score points across complete-suite snapshots</div><svg width="240" height="160" viewBox="0 0 240 160"><polyline points="15,125 115,83 225,30" fill="none" stroke={T.accent} strokeWidth="5"/>{[[15,125],[115,83],[225,30]].map(([x,y],k)=><circle key={k} cx={x} cy={y} r="7" fill={T.accent}/>)}</svg><div style={{fontSize:23}}>65.3 → 71.0 → 77.2%</div><div style={{fontSize:20,marginTop:22}}>Same ten cases; changed policies. Descriptive progress.</div></div></div><Source>Single complete hosted practice suite at 01:44 UTC on 11 Oct. Normalized arena scores; not win probabilities or final results.</Source></>}
